/**
 * Luxembourg postal areas, generated from the national address register (CACLR,
 * Administration du cadastre et de la topographie, CC0), snapshot of 2026-09-28.
 * Commune and canton memberships equal the backend's area tokens (m:lu:<slug>,
 * p:lu:<slug>), so on-device matching agrees with the server's `areas` filter.
 * Do not edit by hand: regenerate with local/tools/generate-lu-postal-data.mjs.
 */

export interface LuxembourgCanton {
  /** Token slug (p:lu:<slug>). */
  slug: string;
  /** Official name. */
  name: string;
}

export interface LuxembourgCommune {
  /** Token slug (m:lu:<slug>). */
  slug: string;
  name: string;
  /** Slug of the canton the commune belongs to. */
  canton: string;
  /** Member postal codes (bare 4 digits). */
  codes: number[];
}

export interface LuxembourgLocality {
  name: string;
  /** Slug of the locality's commune; a few locality names exist in two communes. */
  commune: string;
  /** Representative postal code: the lowest one belonging to this commune only, when one exists. */
  postCode: number;
}

